CREATE TABLE IF NOT EXISTS guild_workspace_leases (
    Id TEXT NOT NULL PRIMARY KEY CHECK(typeof(Id)='text' AND Id=upper(Id) AND length(Id)=36 AND substr(Id,9,1)='-' AND substr(Id,14,1)='-' AND substr(Id,19,1)='-' AND substr(Id,24,1)='-' AND length(replace(Id,'-',''))=32 AND replace(Id,'-','') NOT GLOB '*[^0-9A-F]*' AND Id<>'00000000-0000-0000-0000-000000000000'),
    OwnerKindCode INTEGER NOT NULL CHECK(typeof(OwnerKindCode)='integer' AND OwnerKindCode IN(1,2)),
    PrincipalId TEXT NOT NULL CHECK(typeof(PrincipalId)='text' AND PrincipalId=upper(PrincipalId) AND length(PrincipalId)=36 AND substr(PrincipalId,9,1)='-' AND substr(PrincipalId,14,1)='-' AND substr(PrincipalId,19,1)='-' AND substr(PrincipalId,24,1)='-' AND length(replace(PrincipalId,'-',''))=32 AND replace(PrincipalId,'-','') NOT GLOB '*[^0-9A-F]*' AND PrincipalId<>'00000000-0000-0000-0000-000000000000'),
    QuestId TEXT NULL CHECK(QuestId IS NULL OR (typeof(QuestId)='text' AND QuestId=upper(QuestId) AND length(QuestId)=36 AND substr(QuestId,9,1)='-' AND substr(QuestId,14,1)='-' AND substr(QuestId,19,1)='-' AND substr(QuestId,24,1)='-' AND length(replace(QuestId,'-',''))=32 AND replace(QuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND QuestId<>'00000000-0000-0000-0000-000000000000')),
    RootQuestId TEXT NULL CHECK(RootQuestId IS NULL OR (typeof(RootQuestId)='text' AND RootQuestId=upper(RootQuestId) AND length(RootQuestId)=36 AND substr(RootQuestId,9,1)='-' AND substr(RootQuestId,14,1)='-' AND substr(RootQuestId,19,1)='-' AND substr(RootQuestId,24,1)='-' AND length(replace(RootQuestId,'-',''))=32 AND replace(RootQuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND RootQuestId<>'00000000-0000-0000-0000-000000000000')),
    SessionId TEXT NULL CHECK(SessionId IS NULL OR (typeof(SessionId)='text' AND SessionId=upper(SessionId) AND length(SessionId)=36 AND substr(SessionId,9,1)='-' AND substr(SessionId,14,1)='-' AND substr(SessionId,19,1)='-' AND substr(SessionId,24,1)='-' AND length(replace(SessionId,'-',''))=32 AND replace(SessionId,'-','') NOT GLOB '*[^0-9A-F]*' AND SessionId<>'00000000-0000-0000-0000-000000000000')),
    CampaignId TEXT NULL CHECK(CampaignId IS NULL OR (typeof(CampaignId)='text' AND CampaignId=upper(CampaignId) AND length(CampaignId)=36 AND substr(CampaignId,9,1)='-' AND substr(CampaignId,14,1)='-' AND substr(CampaignId,19,1)='-' AND substr(CampaignId,24,1)='-' AND length(replace(CampaignId,'-',''))=32 AND replace(CampaignId,'-','') NOT GLOB '*[^0-9A-F]*' AND CampaignId<>'00000000-0000-0000-0000-000000000000')),
    WorkspaceId TEXT NOT NULL CHECK(typeof(WorkspaceId)='text' AND WorkspaceId=upper(WorkspaceId) AND length(WorkspaceId)=36 AND substr(WorkspaceId,9,1)='-' AND substr(WorkspaceId,14,1)='-' AND substr(WorkspaceId,19,1)='-' AND substr(WorkspaceId,24,1)='-' AND length(replace(WorkspaceId,'-',''))=32 AND replace(WorkspaceId,'-','') NOT GLOB '*[^0-9A-F]*' AND WorkspaceId<>'00000000-0000-0000-0000-000000000000'),
    InstallationGeneration TEXT NOT NULL CHECK(typeof(InstallationGeneration)='text' AND InstallationGeneration=upper(InstallationGeneration) AND length(InstallationGeneration)=36 AND substr(InstallationGeneration,9,1)='-' AND substr(InstallationGeneration,14,1)='-' AND substr(InstallationGeneration,19,1)='-' AND substr(InstallationGeneration,24,1)='-' AND length(replace(InstallationGeneration,'-',''))=32 AND replace(InstallationGeneration,'-','') NOT GLOB '*[^0-9A-F]*' AND InstallationGeneration<>'00000000-0000-0000-0000-000000000000'),
    WorkspaceRoot TEXT NOT NULL CHECK(typeof(WorkspaceRoot)='text' AND length(CAST(WorkspaceRoot AS BLOB)) BETWEEN 1 AND 32768),
    IdentityJson TEXT NOT NULL CHECK(typeof(IdentityJson)='text' AND length(CAST(IdentityJson AS BLOB)) BETWEEN 1 AND 1048576),
    IdentityDigest TEXT NOT NULL CHECK(typeof(IdentityDigest)='text' AND length(IdentityDigest)=64 AND IdentityDigest NOT GLOB '*[^0-9A-F]*'),
    HostInstanceId TEXT NOT NULL CHECK(typeof(HostInstanceId)='text' AND HostInstanceId=upper(HostInstanceId) AND length(HostInstanceId)=36 AND substr(HostInstanceId,9,1)='-' AND substr(HostInstanceId,14,1)='-' AND substr(HostInstanceId,19,1)='-' AND substr(HostInstanceId,24,1)='-' AND length(replace(HostInstanceId,'-',''))=32 AND replace(HostInstanceId,'-','') NOT GLOB '*[^0-9A-F]*' AND HostInstanceId<>'00000000-0000-0000-0000-000000000000'),
    Epoch INTEGER NOT NULL CHECK(typeof(Epoch)='integer' AND Epoch>=1),
    Revision INTEGER NOT NULL CHECK(typeof(Revision)='integer' AND Revision>=1),
    StateCode INTEGER NOT NULL CHECK(typeof(StateCode)='integer' AND StateCode BETWEEN 1 AND 4),
    HeartbeatAtUtc TEXT NOT NULL CHECK(typeof(HeartbeatAtUtc)='text' AND length(HeartbeatAtUtc)=28),
    ExpiresAtUtc TEXT NOT NULL CHECK(typeof(ExpiresAtUtc)='text' AND length(ExpiresAtUtc)=28),
    InFlightMutationCount INTEGER NOT NULL CHECK(typeof(InFlightMutationCount)='integer' AND InFlightMutationCount>=0),
    EffectKindCode INTEGER NOT NULL CHECK(typeof(EffectKindCode)='integer' AND EffectKindCode IN(0,1)),
    ReasonCode TEXT NULL CHECK(ReasonCode IS NULL OR (typeof(ReasonCode)='text' AND length(CAST(ReasonCode AS BLOB)) BETWEEN 1 AND 128)),
    IdempotencyKey TEXT NOT NULL CHECK(typeof(IdempotencyKey)='text' AND IdempotencyKey=upper(IdempotencyKey) AND length(IdempotencyKey)=36 AND substr(IdempotencyKey,9,1)='-' AND substr(IdempotencyKey,14,1)='-' AND substr(IdempotencyKey,19,1)='-' AND substr(IdempotencyKey,24,1)='-' AND length(replace(IdempotencyKey,'-',''))=32 AND replace(IdempotencyKey,'-','') NOT GLOB '*[^0-9A-F]*' AND IdempotencyKey<>'00000000-0000-0000-0000-000000000000'),
    RequestDigest TEXT NOT NULL CHECK(typeof(RequestDigest)='text' AND length(RequestDigest)=64 AND RequestDigest NOT GLOB '*[^0-9A-F]*'),
    CHECK((OwnerKindCode=1 AND QuestId IS NOT NULL AND RootQuestId IS NOT NULL) OR (OwnerKindCode=2 AND QuestId IS NULL AND RootQuestId IS NULL)),
    CHECK(StateCode<>3 OR InFlightMutationCount=0)
);
